// MineBench Competitor: Choo-Choo Train
// Strategy: Build a detailed Steam Locomotive + Tender + Passenger Cars on a curved track with scenery.
// Focus on 3D sculpting (not flat boxes), correct proportions, and atmospheric details.

const centerX = 128;
const centerZ = 128;
const baseY = 60; // Ground level

// Helper to set a block if it's within bounds
function place(x, y, z, type) {
    if (x >= 0 && x < 256 && y >= 0 && y < 256 && z >= 0 && z < 256) {
        voxel.setBlock(x, y, z, type);
    }
}

// Helper for a box (solid)
function box(x1, y1, z1, x2, y2, z2, type) {
    let minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    let minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    let minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
            for (let z = minZ; z <= maxZ; z++) {
                place(x, y, z, type);
            }
        }
    }
}

// Helper for a hollow box (shell)
function hollowBox(x1, y1, z1, x2, y2, z2, type) {
    let minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    let minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    let minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
        for (let y = minY; y <= maxY; y++) {
            for (let z = minZ; z <= maxZ; z++) {
                if (x === minX || x === maxX || y === minY || y === maxY || z === minZ || z === maxZ) {
                    place(x, y, z, type);
                }
            }
        }
    }
}

// Helper for a cylinder along X axis
function cylX(cx, cy, cz, r, len, type) {
    let r2 = r * r;
    for (let x = 0; x < len; x++) {
        for (let y = -r; y <= r; y++) {
            for (let z = -r; z <= r; z++) {
                if (y*y + z*z <= r2) {
                    place(cx + x, cy + y, cz + z, type);
                }
            }
        }
    }
}

// Helper for a cylinder along Z axis
function cylZ(cx, cy, cz, r, len, type) {
    let r2 = r * r;
    for (let z = 0; z < len; z++) {
        for (let x = -r; x <= r; x++) {
            for (let y = -r; y <= r; y++) {
                if (x*x + y*y <= r2) {
                    place(cx + x, cy + y, cz + z, type);
                }
            }
        }
    }
}

// Helper for a sphere-ish blob
function blob(cx, cy, cz, rx, ry, rz, type) {
    let rrx = rx*rx, rry = ry*ry, rrz = rz*rz;
    for (let x = -rx; x <= rx; x++) {
        for (let y = -ry; y <= ry; y++) {
            for (let z = -rz; z <= rz; z++) {
                if ((x*x)/rrx + (y*y)/rry + (z*z)/rrz <= 1.0) {
                    place(cx+x, cy+y, cz+z, type);
                }
            }
        }
    }
}

// --- Environment Setup ---
// Ground
box(0, 58, 0, 255, 59, 255, 'grass_block');
box(0, 57, 0, 255, 57, 255, 'dirt');

// Track (Curved slightly for dynamism)
// We'll build a straight section for the train to sit on for simplicity and stability, 
// but add scenery around it.
const trackZ = 128;
const trackY = 60;
// Rails
for (let x = 0; x < 256; x++) {
    place(x, trackY, trackZ - 4, 'iron_block');
    place(x, trackY, trackZ + 4, 'iron_block');
}
// Sleepers (Ties)
for (let z = trackZ - 6; z <= trackZ + 6; z++) {
    if ((z - trackZ) % 2 === 0) { // Every other block
        for (let x = 10; x < 246; x++) {
             // Only place under the train area roughly, or full width?
             // Full width ties look messy. Let's do a ballast bed.
        }
    }
}
// Ballast
for (let x = 10; x < 246; x++) {
    for (let z = trackZ - 8; z <= trackZ + 8; z++) {
        place(x, trackY, z, 'gravel');
    }
}

// --- Steam Locomotive ---
// Dimensions: Length ~40 blocks, Height ~12 blocks, Width ~8 blocks
const locoXStart = 20;
const locoZ = trackZ; // Centered on track
const locoY = trackY + 1; // On rails

// 1. Cow Catcher (Pilot)
// V-shape at front
for (let x = locoXStart - 5; x < locoXStart; x++) {
    let width = Math.max(2, (x - (locoXStart - 5)) * 1.5);
    for (let z = -width; z <= width; z++) {
        place(x, locoY + 1, locoZ + z, 'iron_block');
    }
    // Vertical bars
    if (x === locoXStart - 4 || x === locoXStart - 2) {
         for (let y = locoY + 1; y < locoY + 5; y++) {
             place(x, y, locoZ, 'iron_block');
         }
    }
}

// 2. Boiler Section
// Main Cylinder
const boilerLen = 20;
const boilerR = 4;
cylX(locoXStart + 5, locoY + 5, locoZ, boilerR, boilerLen, 'iron_block');
// Firebox (Back of boiler)
const fireboxX = locoXStart + 5 + boilerLen;
blob(fireboxX + 2, locoY + 5, locoZ, 3, 4, 4, 'bricks');
// Smokebox (Front of boiler)
const smokeboxX = locoXStart + 5;
blob(smokeboxX - 2, locoY + 5, locoZ, 2, 4, 4, 'iron_block');

// Boiler Bands
for (let x = locoXStart + 6; x < fireboxX; x += 3) {
    for (let y = -boilerR; y <= boilerR; y++) {
        for (let z = -boilerR; z <= boilerR; z++) {
            if (y*y + z*z <= boilerR*boilerR && (Math.abs(y) < 1 || Math.abs(z) < 1 || x % 3 === 0)) {
                // Just a ring
                place(x, locoY + 5 + y, locoZ + z, 'gold_block');
            }
        }
    }
}
// Better Boiler Bands (Simple rings)
for (let x = locoXStart + 6; x < fireboxX; x += 4) {
    for (let y = -boilerR; y <= boilerR; y++) {
        for (let z = -boilerR; z <= boilerR; z++) {
             if (y*y + z*z <= boilerR*boilerR) {
                 place(x, locoY + 5 + y, locoZ + z, 'gold_block');
             }
        }
    }
}

// 3. Cabin (Cab)
// Behind firebox
const cabStart = fireboxX + 2;
const cabLen = 8;
hollowBox(cabStart, locoY + 1, locoZ - 4, cabStart + cabLen, locoY + 10, locoZ + 4, 'oak_planks');
// Roof
box(cabStart - 1, locoY + 10, locoZ - 5, cabStart + cabLen + 2, locoY + 12, locoZ + 5, 'bricks');
// Windows
for (let x = cabStart + 1; x < cabStart + cabLen; x += 2) {
    place(x, locoY + 7, locoZ - 4, 'glass');
    place(x, locoY + 7, locoZ + 4, 'glass');
}
// Door
place(cabStart + 3, locoY + 1, locoZ - 5, 'oak_door'); // Note: door logic simple
place(cabStart + 3, locoY + 2, locoZ - 5, 'oak_door');

// 4. Wheels (Driving Wheels)
const wheelBase1 = cabStart - 8;
const wheelBase2 = cabStart - 16;
function buildWheelSet(cx, cy, cz) {
    // Large driving wheels
    const r = 3;
    for (let y = -r; y <= r; y++) {
        for (let z = -r; z <= r; z++) {
            if (y*y + z*z <= r*r) {
                place(cx, cy + y, cz + z, 'iron_block');
                // Spokes
                if (Math.abs(y) < 1 || Math.abs(z) < 1) {
                     place(cx, cy + y, cz + z, 'gold_block');
                }
            }
        }
    }
    // Axle connecting sides
    for (let x = -1; x <= 1; x++) {
        for (let z = -r-2; z <= r+2; z++) {
             if (z*z > r*r) place(cx+x, cy, cz+z, 'iron_block');
        }
    }
}

buildWheelSet(wheelBase1, locoY + 3, locoZ - 4);
buildWheelSet(wheelBase1, locoY + 3, locoZ + 4);
buildWheelSet(wheelBase2, locoY + 3, locoZ - 4);
buildWheelSet(wheelBase2, locoY + 3, locoZ + 4);

// Connecting Rods (Visual only)
line(wheelBase1, locoY + 3, locoZ - 5, wheelBase2, locoY + 3, locoZ - 5, 'iron_block');
line(wheelBase1, locoY + 3, locoZ + 5, wheelBase2, locoY + 3, locoZ + 5, 'iron_block');

// 5. Smokestack
const stackX = smokeboxX - 4;
cylZ(stackX, locoY + 9, locoZ, 1, 6, 'iron_block');
// Chimney cap
blob(stackX, locoY + 12, locoZ, 2, 1, 2, 'gold_block');

// 6. Dome / Sand Dome
blob(smokeboxX - 6, locoY + 9, locoZ, 2, 2, 2, 'gold_block');

// 7. Headlight
place(smokeboxX - 1, locoY + 8, locoZ, 'glowstone');
place(smokeboxX - 1, locoY + 8, locoZ - 1, 'glass');
place(smokeboxX - 1, locoY + 8, locoZ + 1, 'glass');

// --- Tender (Coal Car) ---
const tenderStart = cabStart + cabLen;
const tenderLen = 12;
hollowBox(tenderStart, locoY + 1, locoZ - 4, tenderStart + tenderLen, locoY + 7, locoZ + 4, 'oak_planks');
// Coal load
blob(tenderStart + 3, locoY + 8, locoZ, 4, 2, 3, 'coal_block'); // Using black_wool or similar if coal_block not avail. Let's use black_wool.
for(let x=tenderStart+1; x<tenderStart+tenderLen-1; x++) {
    for(let z=-3; z<=3; z++) {
        let h = Math.random() > 0.5 ? 1 : 0;
        place(x, locoY + 7 + h, locoZ + z, 'black_wool');
    }
}
// Roof
box(tenderStart - 1, locoY + 7, locoZ - 5, tenderStart + tenderLen + 2, locoY + 8, locoZ + 5, 'bricks');

// --- Passenger Car 1 ---
const car1Start = tenderStart + tenderLen + 4;
const carLen = 20;
const carHeight = 7;
const carWidth = 6;

// Body
hollowBox(car1Start, locoY + 1, locoZ - carWidth/2, car1Start + carLen, locoY + carHeight, locoZ + carWidth/2, 'red_wool');
// Floor/Roof
box(car1Start, locoY + 1, locoZ - carWidth/2, car1Start + carLen, locoY + 1, locoZ + carWidth/2, 'stone_bricks');
box(car1Start, locoY + carHeight, locoZ - carWidth/2, car1Start + carLen, locoY + carHeight, locoZ + carWidth/2, 'bricks');

// Windows
for (let x = car1Start + 2; x < car1Start + carLen; x += 3) {
    place(x, locoY + 4, locoZ - carWidth/2, 'glass');
    place(x, locoY + 4, locoZ + carWidth/2, 'glass');
}

// Wheels (Smaller)
const carWheelBase = car1Start + 5;
function buildSmallWheel(cx, cy, cz) {
    const r = 2;
    for (let y = -r; y <= r; y++) {
        for (let z = -r; z <= r; z++) {
            if (y*y + z*z <= r*r) place(cx, cy + y, cz + z, 'iron_block');
        }
    }
}
buildSmallWheel(carWheelBase, locoY + 3, locoZ - carWidth/2 - 1);
buildSmallWheel(carWheelBase, locoY + 3, locoZ + carWidth/2 + 1);
buildSmallWheel(carWheelBase + carLen - 5, locoY + 3, locoZ - carWidth/2 - 1);
buildSmallWheel(carWheelBase + carLen - 5, locoY + 3, locoZ + carWidth/2 + 1);

// --- Passenger Car 2 ---
const car2Start = car1Start + carLen + 4;
hollowBox(car2Start, locoY + 1, locoZ - carWidth/2, car2Start + carLen, locoY + carHeight, locoZ + carWidth/2, 'blue_wool');
box(car2Start, locoY + 1, locoZ - carWidth/2, car2Start + carLen, locoY + 1, locoZ + carWidth/2, 'stone_bricks');
box(car2Start, locoY + carHeight, locoZ - carWidth/2, car2Start + carLen, locoY + carHeight, locoZ + carWidth/2, 'bricks');

for (let x = car2Start + 2; x < car2Start + carLen; x += 3) {
    place(x, locoY + 4, locoZ - carWidth/2, 'glass');
    place(x, locoY + 4, locoZ + carWidth/2, 'glass');
}

const car2WheelBase = car2Start + 5;
buildSmallWheel(car2WheelBase, locoY + 3, locoZ - carWidth/2 - 1);
buildSmallWheel(car2WheelBase, locoY + 3, locoZ + carWidth/2 + 1);
buildSmallWheel(car2WheelBase + carLen - 5, locoY + 3, locoZ - carWidth/2 - 1);
buildSmallWheel(car2WheelBase + carLen - 5, locoY + 3, locoZ + carWidth/2 + 1);

// --- Scenery / Atmosphere ---

// Trees
function buildTree(x, y, z) {
    // Trunk
    box(x, y, z, x, y + 4, z, 'oak_log');
    // Leaves
    for (let lx = -2; lx <= 2; lx++) {
        for (let ly = 0; ly <= 3; ly++) {
            for (let lz = -2; lz <= 2; lz++) {
                if (Math.abs(lx) + Math.abs(ly) + Math.abs(lz) < 4) {
                    place(x + lx, y + 4 + ly, z + lz, 'oak_leaves');
                }
            }
        }
    }
}

// Place trees randomly around the track
for (let i = 0; i < 20; i++) {
    let tx = Math.floor(Math.random() * 100) + 10;
    let tz = trackZ + (Math.random() > 0.5 ? 1 : -1) * (Math.floor(Math.random() * 30) + 20);
    buildTree(tx, 60, tz);
}

// Smoke Clouds (Particle effect using white wool/glass)
const smokeStartX = stackX - 5;
for (let i = 0; i < 15; i++) {
    let sx = smokeStartX - Math.random() * 20;
    let sy = locoY + 12 + Math.random() * 10;
    let sz = locoZ + (Math.random() - 0.5) * 10;
    blob(sx, sy, sz, 1 + Math.random(), 1 + Math.random(), 1 + Math.random(), 'white_wool');
}

// Platform at one end
box(10, 60, trackZ - 12, 30, 62, trackZ - 2, 'stone_bricks');
box(10, 63, trackZ - 12, 30, 63, trackZ - 2, 'cobblestone');
// Posts
for (let x = 12; x <= 28; x += 4) {
    box(x, 63, trackZ - 12, x, 75, trackZ - 12, 'oak_log');
}
// Roof over platform
box(10, 75, trackZ - 12, 30, 75, trackZ - 2, 'bricks');

// Signpost
place(15, 64, trackZ - 10, 'oak_log');
box(14, 66, trackZ - 10, 16, 67, trackZ - 10, 'spruce_planks'); // Assuming spruce available? No. Use oak.
box(14, 66, trackZ - 10, 16, 67, trackZ - 10, 'oak_planks');

// Station Building (Behind platform)
box(5, 60, trackZ - 20, 35, 70, trackZ - 10, 'stone_bricks');
box(5, 70, trackZ - 20, 35, 72, trackZ - 10, 'bricks'); // Roof
// Door
place(20, 60, trackZ - 9, 'oak_door');
place(20, 61, trackZ - 9, 'oak_door');
// Windows
place(10, 65, trackZ - 9, 'glass');
place(30, 65, trackZ - 9, 'glass');
